CLASSROOM/css/style.css

/* http://meyerweb.com/eric/tools/css/reset/ 
   v2.0 | 20110126
   License: none (public domain)
*/

html, body, div, span, applet, object, iframe,
h1, h2, h3, h4, h5, h6, p, blockquote, pre,
a, abbr, acronym, address, big, cite, code,
del, dfn, em, img, ins, kbd, q, s, samp,
small, strike, strong, sub, sup, tt, var,
b, u, i, center,
dl, dt, dd, ol, ul, li,
fieldset, form, label, legend,
table, caption, tbody, tfoot, thead, tr, th, td,
article, aside, canvas, details, embed, 
figure, figcaption, footer, header, hgroup, 
menu, nav, output, ruby, section, summary,
time, mark, audio, video {
	margin: 0;
	padding: 0;
	border: 0;
	font-size: 100%;
	font: inherit;
	vertical-align: baseline;
}
/* HTML5 display-role reset for older browsers */
article, aside, details, figcaption, figure, 
footer, header, hgroup, menu, nav, section {
	display: block;
}
body {
	line-height: 1;
}
ol, ul {
	list-style: none;
}
blockquote, q {
	quotes: none;
}
blockquote:before, blockquote:after,
q:before, q:after {
	content: '';
	content: none;
}
table {
	border-collapse: collapse;
	border-spacing: 0;
}

@charset "UTF-8";

@import url('http://fonts.googleapis.com/earlyaccess/nanumgothic.css');
@import url('http://fonts.googleapis.com/earlyaccess/nanummyeongjo.css');

.wrap {
	padding: 24px 24px 50px;
	font-family: 'NanumGothic', 'Nanum Gothic', 'sans-serif';
	font-size: 14px;
	line-height: 1.2;
	color: #222;
}
.header {
	position: relative;
	margin-bottom: 24px;
}
.header-title {
	margin-bottom: 24px;
	font-family: 'NanumMyeongjo', 'Nanum Myeongjo', 'sans-serif';
	font-size: 24px;
}
.header-picture-image {
	width: 100%;
	max-width: 150px;
	vertical-align: top;
}
.content {
	position: relative;
}
.section {
	position: relative;
	margin-top: 60px;
}
.section-title {
	font-size: 16px;
	font-weight: bold;
}
.article {
	margin-top: 24px;
}
.section-title + .article {
	margin-top: 6px;
	padding-top: 24px;
	border-top: 3px solid #222;
}
.article-title {
	position: relative;
	font-weight: bold;
}
.article-list {
	list-style: disc;
	padding-left: 18px;
}
.article-item {
	margin-top: 6px;
}
.article-text {
	margin-top: 6px;
}
.footer {
	margin-top: 60px;
	padding-top: 12px;
	border-top: 1px solid #e9e9e9;
	font-size: 12px;
	color: #999;
	text-align: right;
}

@media (min-width: 600px) {

    .wrap {
        max-width: 700px;
        margin: 0 auto;
        padding: 50px 50px 100px;
    }
    /* .header {
        overflow: hidden;
    } */
    .header::after {
        content: '';
        display: block;
        clear: both;
    }
    .header-title {
        float: left;
        width: 70%;
    }
    .header-picture {
        float: right;
        width: 28%;
    }
    .header-picture-image {
	    max-width: 100%;
    }
    .section::after {
        content: '';
        display: block;
        clear: both;
    }
    .section-title {
        position: sticky;
        top: 10px;
        float: left;
        width: 28%;
        padding-top: 12px;
        border-top: 3px solid #222;
    }
    .article {
        float: right;
        width: 70%;
    }
    .section-title + .article {
        margin-top: 0;
        padding-top: 12px;
    }   
} /* @media (min-width: 600px) */
